'use strict';
const STORE='gat-workspace-v2';
let customQuestions=[],attempts=[],settings={mode:'random'},pendingImport=null,workbook=null,lastImport=null,reviewFilter='all',currentReport=null;
const clone=x=>JSON.parse(JSON.stringify(x)), uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
const answered=a=>Number.isInteger(a)&&a>=0&&a<4;
function warning(message){const el=$('#storage-warning');if(el){el.hidden=!message;el.textContent=message}}
function snapshot(){return {format:'gat-workspace',version:2,exportedAt:new Date().toISOString(),customQuestions,history,attempts,settings,activeExam:exam}}
function save(){try{localStorage.setItem(STORE,JSON.stringify(snapshot()));localStorage.removeItem('gat-progress-v1');warning('');return true}catch{warning('لم تُحفظ آخر التغييرات في المتصفح. صدّر نسخة احتياطية من إدارة البيانات قبل إغلاق الصفحة.');return false}}
function record(q,a){history.push({id:q.id,category:q.category,section:q.section,correct:a===q.answer,at:new Date().toISOString()});save()}
function rebuild(){const map=new Map(window.GAT_BASE.questions.map(q=>[q.id,clone(q)]));customQuestions.forEach(q=>map.set(q.id,clone(q)));data={...window.GAT_BASE,questions:[...map.values()]};question=null;section='الكل';category='الكل';difficulty='الكل'}
function shuffle(list){const a=[...list];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function freshQuestions(){const previous=new Set(attempts.filter(a=>a.mode==='random').at(-1)?.qs.map(q=>q.id)||[]);const choose=s=>{const all=data.questions.filter(q=>q.section===s);if(all.length<30)throw Error('يلزم وجود ٣٠ سؤالًا على الأقل في كل قسم.');return [...shuffle(all.filter(q=>!previous.has(q.id))),...shuffle(all.filter(q=>previous.has(q.id)))].slice(0,30)};return shuffle([...choose('لفظي'),...choose('كمي')])}
function duration(seconds){seconds=Math.max(0,Math.floor(seconds));return `${num(Math.floor(seconds/60))} د ${num(seconds%60)} ث`}
function remaining(){const sec=Math.max(0,Math.ceil((exam.deadline-Date.now())/1000));return `${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`}
function exams(){
 $('#main').innerHTML=title('كل محاولة، فرصة جديدة','اختر نوع الاختبار قبل البدء. المدة المقترحة ٧٥ دقيقة، وليست مدة رسمية.')+`<section class="card mode-card"><h2>كيف تختار أسئلة امتحانك؟</h2><div class="mode-options"><label><input type="radio" name="exam-mode" value="random" ${settings.mode==='random'?'checked':''}> مجموعة متجددة في كل محاولة</label><label><input type="radio" name="exam-mode" value="fixed" ${settings.mode==='fixed'?'checked':''}> أحد النماذج الثابتة الخمسة</label></div><p class="muted">المتجدد يسحب ٣٠ لفظي و٣٠ كمي، ويستبعد أسئلة آخر اختبار متجدد قدر الإمكان. قد تعود أسئلة من محاولات أقدم. النموذج الثابت يحتفظ بالأسئلة وترتيبها لتقارن تحسّنك.</p></section>`+(settings.mode==='random'?`<section class="card exam-card"><span class="tag">متجدد</span><h2>اختبار جديد من بنكك الحالي</h2><p>٦٠ سؤالًا من ${num(data.questions.length)} سؤال متاح، بما فيها إضافاتك المعتمدة.</p><button id="random-start" class="primary">توليد الاختبار والبدء ←</button></section>`:`<div class="grid">${Object.entries(data.tests).map(([name,ids],i)=>`<section class="card exam-card"><span class="exam-number">نموذج ثابت ${num(i+1)}</span><h2>${esc(name)}</h2><p>${num(ids.length)} سؤالًا · ٣٠ لفظي + ٣٠ كمي</p><p>تكرار هذا النموذج يعرض الأسئلة نفسها. الإضافات الجديدة تدخل الاختبارات المتجددة.</p><button class="primary" data-exam="${esc(name)}">ابدأ النموذج ←</button></section>`).join('')}</div>`);
 document.querySelectorAll('[name="exam-mode"]').forEach(el=>el.onchange=()=>{settings.mode=el.value;save();exams()});$('#random-start')?.addEventListener('click',()=>startExam('اختبار متجدد','random'));document.querySelectorAll('[data-exam]').forEach(el=>el.onclick=()=>startExam(el.dataset.exam,'fixed'));
}
function startExam(name,mode='fixed'){
 if(exam)throw Error('يوجد اختبار جارٍ.');if(!['fixed','random'].includes(mode))throw Error('نوع اختبار غير صالح');if(mode==='fixed'&&!Object.hasOwn(data.tests,name))throw Error('اختبار غير موجود');
 const qs=mode==='random'?freshQuestions():data.tests[name].map(id=>data.questions.find(q=>q.id===id));if(qs.some(q=>!q))throw Error('تعذّر إيجاد بعض أسئلة النموذج.');
 const now=Date.now();exam={id:uid(),name,mode,qs:clone(qs),answers:Array(qs.length).fill(null),times:Array(qs.length).fill(0),flags:Array(qs.length).fill(false),index:0,startedAt:now,deadline:now+75*60000,lastTouch:now};save();activate('exams');renderExam();runTimer();
}
function touchExam(){if(!exam)return;const now=Math.min(Date.now(),exam.deadline);const elapsed=Math.max(0,now-exam.lastTouch);exam.times[exam.index]+=elapsed/1000;exam.lastTouch=now}
function runTimer(){clearInterval(timer);timer=setInterval(()=>{if(!exam)return;if(Date.now()>=exam.deadline){finishExam('timeout');return}if($('#time'))$('#time').textContent=remaining();if(Math.floor(Date.now()/1000)%10===0){touchExam();save()}},1000)}
function setExamAnswer(value){if(!exam||!answered(value))throw Error('إجابة غير صالحة');if(Date.now()>=exam.deadline){finishExam('timeout');return}touchExam();exam.answers[exam.index]=value;save();renderExam()}
function jump(index){if(!exam||index<0||index>=exam.qs.length)return;touchExam();exam.index=index;save();renderExam()}
function renderExam(){if(!exam)return exams();const e=exam,q=e.qs[e.index],done=e.answers.filter(answered).length;$('#main').innerHTML=title(e.name,e.mode==='random'?'مجموعة متجددة · تُحفظ المحاولة ويمكن استكمالها قبل انتهاء الوقت.':'نموذج ثابت · تُحفظ المحاولة ويمكن استكمالها قبل انتهاء الوقت.')+`<section class="card"><div class="qmeta"><b>السؤال ${num(e.index+1)} من ${num(e.qs.length)}</b><span class="timer" id="time">${remaining()}</span><span>${num(done)} إجابة</span></div><div class="progress-track"><span style="width:${done/e.qs.length*100}%"></span></div>${qMarkup(q,e.answers[e.index],false)}<label class="flag-label"><input id="flag" type="checkbox" ${e.flags[e.index]?'checked':''}> علّم هذا السؤال للمراجعة</label><div class="actions"><button id="prev" ${e.index===0?'disabled':''}>السابق</button><button id="finish">إنهاء وعرض النتيجة</button><button class="primary" id="next" ${e.index===e.qs.length-1?'disabled':''}>التالي ←</button></div><details class="question-map"><summary>الانتقال إلى سؤال · ${num(e.qs.length-done)} دون إجابة</summary><div class="question-grid">${e.qs.map((_,i)=>`<button data-jump="${i}" class="${i===e.index?'current':''} ${answered(e.answers[i])?'done':''}" aria-label="السؤال ${i+1}${e.flags[i]?' معلّم للمراجعة':''}${answered(e.answers[i])?' تمت إجابته':''}" ${i===e.index?'aria-current="step"':''}>${num(i+1)}${e.flags[i]?' ★':''}</button>`).join('')}</div></details></section>`;
 document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>setExamAnswer(+b.dataset.answer));$('#prev').onclick=()=>jump(e.index-1);$('#next').onclick=()=>jump(e.index+1);$('#flag').onchange=ev=>{e.flags[e.index]=ev.target.checked;save()};document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>jump(+b.dataset.jump));$('#finish').onclick=()=>{if(confirm(`أجبت عن ${done} من ${e.qs.length}. هل تريد إنهاء المحاولة وحفظ النتيجة؟`))finishExam('submitted')};
}
function finishExam(reason='submitted'){if(!exam)return;touchExam();clearInterval(timer);const e=exam;e.finishedAt=Math.min(Date.now(),e.deadline);e.reason=reason;delete e.lastTouch;attempts.push(clone(e));e.qs.forEach((q,i)=>{if(answered(e.answers[i]))history.push({id:q.id,category:q.category,section:q.section,correct:q.answer===e.answers[i],at:new Date(e.finishedAt).toISOString(),examId:e.id})});exam=null;save();activate('reports');reviewFilter='all';showReport(e.id)}
function counts(e,indices=e.qs.map((_,i)=>i)){let correct=0,wrong=0,blank=0;indices.forEach(i=>{if(!answered(e.answers[i]))blank++;else if(e.answers[i]===e.qs[i].answer)correct++;else wrong++});return {correct,wrong,blank,total:indices.length,percent:indices.length?Math.round(correct/indices.length*100):0}}
function reportSummary(e){const c=counts(e);return `<div class="stats report-stats"><div class="stat"><span>النتيجة من كل الأسئلة</span><strong>${num(c.percent)}٪</strong></div><div class="stat"><span>إجابات صحيحة</span><strong>${num(c.correct)}</strong></div><div class="stat"><span>إجابات غير صحيحة</span><strong>${num(c.wrong)}</strong></div><div class="stat"><span>دون إجابة</span><strong>${num(c.blank)}</strong></div></div><p class="muted">${new Date(e.startedAt).toLocaleString('ar-SA')} · ${e.mode==='random'?'مجموعة متجددة':'نموذج ثابت'} · الوقت المستغرق: ${duration((e.finishedAt-e.startedAt)/1000)} · ${e.reason==='timeout'?'انتهى الوقت':'إنهاء يدوي'}</p>`}
function breakdown(e,field){return [...new Set(e.qs.map(q=>q[field]))].map(key=>{const ix=e.qs.flatMap((q,i)=>q[field]===key?[i]:[]),c=counts(e,ix);return {key,...c}}).sort((a,b)=>a.percent-b.percent)}
function breakdownTable(e,field){return `<div class="table-wrap"><table><thead><tr><th>${field==='section'?'القسم':'المهارة'}</th><th>صحيح</th><th>خطأ</th><th>متروك</th><th>النسبة</th></tr></thead><tbody>${breakdown(e,field).map(g=>`<tr><th>${esc(g.key)}</th><td>${num(g.correct)}</td><td>${num(g.wrong)}</td><td>${num(g.blank)}</td><td>${num(g.percent)}٪</td></tr>`).join('')}</tbody></table></div>`}
function reportQuestion(e,i){const q=e.qs[i],a=e.answers[i],status=!answered(a)?'blank':a===q.answer?'correct':'wrong';return `<article class="review"><div class="qmeta"><span class="status ${status==='correct'?'':'error'}">${num(i+1)} · ${status==='correct'?'صحيحة':status==='wrong'?'غير صحيحة':'لم تُجب'}</span><span>${esc(q.section)} · ${esc(q.difficulty)} · ${duration(e.times[i]||0)}${e.flags[i]?' · ★ معلّم':''}</span></div><h3>${esc(q.text)}</h3><ol class="review-options">${q.options.map((o,j)=>`<li class="${j===q.answer?'answer-key':''}">${'أبجد'[j]} — ${esc(o)} ${j===q.answer?' ✓ الصحيحة':''}${j===a?' ← إجابتك':''}</li>`).join('')}</ol><p><b>شرح الحل:</b> ${esc(q.explanation||'لا يوجد شرح مرفق لهذا السؤال.')}</p><p class="muted">${esc(q.category)} · ${esc(q.id)}</p></article>`}
function showReport(id){const e=attempts.find(a=>a.id===id);if(!e)return reports();currentReport=id;activate('reports');const c=counts(e);const low=breakdown(e,'category').filter(g=>g.percent<70).slice(0,3);const indices=e.qs.flatMap((q,i)=>reviewFilter==='all'||(reviewFilter==='wrong'&&answered(e.answers[i])&&e.answers[i]!==q.answer)||(reviewFilter==='blank'&&!answered(e.answers[i]))||(reviewFilter==='flagged'&&e.flags[i])?[i]:[]);
 $('#main').innerHTML=title('نتيجة '+esc(e.name),'تفاصيل محفوظة لهذه المحاولة كما كانت وقت إجرائها. النسبة تدريبية وليست درجة رسمية.')+reportSummary(e)+`<div class="actions report-actions"><button id="report-back">كل المحاولات</button><button id="report-download">تنزيل تقرير HTML</button><button id="report-print">طباعة / PDF</button></div><div class="grid"><section class="card"><h2>الأداء حسب القسم</h2>${breakdownTable(e,'section')}</section><section class="card"><h2>ما الذي تراجعه الآن؟</h2>${low.length?`<p>أقل المهارات أداءً في هذه المحاولة:</p><ul>${low.map(g=>`<li>${esc(g.key)} — ${num(g.percent)}٪</li>`).join('')}</ul>`:`<p>${c.percent===100?'أجبت عن كل الأسئلة بشكل صحيح.':'راجع الأسئلة غير الصحيحة والمتروكة أدناه.'}</p>`}<p class="muted">الأولوية مبنية على هذه المحاولة فقط. زمن السؤال هو زمن العرض المرصود فقط؛ وقت الانقطاع مستقل ولا يُنسب إلى سؤال لم يُعرض.</p></section></div><section class="card spaced"><h2>تفصيل المهارات</h2>${breakdownTable(e,'category')}</section><section class="card spaced"><div class="topline"><h2>مراجعة الأسئلة</h2><label>اعرض<select id="review-filter"><option value="all">كل الأسئلة</option><option value="wrong">غير الصحيحة</option><option value="blank">دون إجابة</option><option value="flagged">المعلّمة للمراجعة</option></select></label></div><p class="muted">${num(indices.length)} سؤالًا</p>${indices.length?indices.map(i=>reportQuestion(e,i)).join(''):'<p>لا توجد أسئلة ضمن هذا الاختيار.</p>'}</section>`;
 $('#review-filter').value=reviewFilter;$('#review-filter').onchange=ev=>{reviewFilter=ev.target.value;showReport(id)};$('#report-back').onclick=reports;$('#report-download').onclick=()=>downloadReport(e);$('#report-print').onclick=()=>{reviewFilter='all';showReport(id);window.print()};
}
function reports(){currentReport=null;$('#main').innerHTML=title('نتائج امتحاناتك','كل محاولة لها سجل مستقل: الأسئلة، إجاباتك، الشرح، الوقت، والأداء حسب المهارة.')+(exam?`<section class="card spaced"><h2>لديك اختبار جارٍ</h2><button id="resume" class="primary">استكمال الاختبار</button></section>`:'')+(attempts.length?`<div class="grid">${[...attempts].reverse().map((e)=>`<section class="card"><div class="qmeta"><span>${e.mode==='random'?'متجدد':'ثابت'}</span><span>${new Date(e.startedAt).toLocaleDateString('ar-SA')}</span></div><h2>${esc(e.name)}</h2><div class="results-score">${num(counts(e).percent)}٪</div><p class="muted">${num(counts(e).correct)} من ${num(e.qs.length)} صحيحة · ${duration((e.finishedAt-e.startedAt)/1000)}</p><button class="primary" data-report="${esc(e.id)}">عرض النتيجة المفصّلة</button></section>`).join('')}</div>`:`<section class="card empty"><h2>لا توجد امتحانات مكتملة بعد</h2><p>ستظهر هنا نتائج الامتحانات التي تنهيها بعد هذا التحديث.</p><button class="primary" id="to-exam">ابدأ امتحانًا</button></section>`);document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>{reviewFilter='all';showReport(b.dataset.report)});$('#to-exam')?.addEventListener('click',()=>go('exams'));$('#resume')?.addEventListener('click',()=>go('exams'))}
function downloadBlob(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function downloadReport(e){const html=`<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>نتيجة ${esc(e.name)}</title><style>body{font:17px/1.9 Tahoma,Arial;max-width:960px;margin:30px auto;padding:20px;color:#18352e}.stats{display:flex;gap:30px;flex-wrap:wrap}.stat{display:grid}.stat strong{font-size:30px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ddd;padding:8px;text-align:right}.review{border-top:1px solid #ccc;padding:20px 0;break-inside:avoid}.answer-key{color:#285f28;font-weight:bold}.muted{color:#59685f}.review-options{list-style:none;padding:0}.qmeta{font-size:14px}.error{color:#a33}h3{white-space:pre-line}button{padding:12px}@media print{button{display:none}}</style><button onclick="window.print()">طباعة / حفظ PDF</button><h1>نتيجة ${esc(e.name)}</h1>${reportSummary(e)}<p>درجة تدريبية، وليست درجة القدرات الرسمية.</p><h2>حسب القسم</h2>${breakdownTable(e,'section')}<h2>حسب المهارة</h2>${breakdownTable(e,'category')}<h2>الأسئلة والإجابات والشروح</h2>${e.qs.map((_,i)=>reportQuestion(e,i)).join('')}</html>`;downloadBlob(`GAT_Report_${e.id}.html`,html,'text/html;charset=utf-8')}

// XLSX: ZIP + XML, with no remote service and no formula evaluation.
const fieldNames={id:['معرف السؤال','المعرف','id'],section:['القسم','section'],category:['التصنيف','المهارة','category'],skill:['المهارة الفرعية','skill'],difficulty:['الصعوبة','الصعوبة الفعلية','difficulty'],text:['السؤال','نص السؤال','question','text'],a:['الخيار أ','الخيار ا','أ','ا','option a'],b:['الخيار ب','ب','option b'],c:['الخيار ج','ج','option c'],d:['الخيار د','د','option d'],answer:['الإجابة الصحيحة','الاجابة الصحيحة','answer'],explanation:['الشرح','شرح الإجابة','explanation'],source:['المرجع','source']};
const norm=s=>String(s??'').trim().replace(/[\u200e\u200f\ufeff]/g,'').replace(/\s+/g,' ').toLowerCase();
const requiredFields=['id','section','category','difficulty','text','a','b','c','d','answer','explanation'];
function elements(node,name){return Array.from(node.getElementsByTagNameNS('*',name))}
function xml(text){const doc=new DOMParser().parseFromString(text,'application/xml');if(doc.getElementsByTagName('parsererror').length)throw Error('محتوى XML غير صالح داخل الملف.');return doc}
function zipPath(base,target){if(target.startsWith('/'))return target.slice(1);const result=base.split('/');result.pop();for(const segment of target.split('/')){if(segment==='..')result.pop();else if(segment!=='.')result.push(segment)}return result.join('/')}
async function xmlPart(zip,path){const file=zip.file(path);if(!file)throw Error('الملف لا يحتوي على ورقة Excel صالحة.');if(file._data?.uncompressedSize>25*1024*1024)throw Error('ورقة العمل كبيرة جدًا. قسّمها إلى ملفات أصغر.');const s=await file.async('string');if(s.length>25*1024*1024)throw Error('ورقة العمل كبيرة جدًا.');return xml(s)}
async function openWorkbook(file){
 if(!file.name.toLowerCase().endsWith('.xlsx'))throw Error('اختر ملف .xlsx. احفظ ملفات .xls القديمة بصيغة .xlsx أولًا.');if(file.size>15*1024*1024)throw Error('الحد الأقصى ١٥ ميجابايت لملف الاستيراد.');const zip=await JSZip.loadAsync(await file.arrayBuffer());const book=await xmlPart(zip,'xl/workbook.xml'),rels=await xmlPart(zip,'xl/_rels/workbook.xml.rels');const targets=new Map(elements(rels,'Relationship').filter(n=>n.getAttribute('TargetMode')!=='External').map(n=>[n.getAttribute('Id'),zipPath('xl/workbook.xml',n.getAttribute('Target'))]));const sheets=elements(book,'sheet').map(n=>({name:n.getAttribute('name'),path:targets.get(n.getAttribute('r:id')||n.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id'))})).filter(s=>s.path);if(!sheets.length)throw Error('لا توجد أوراق قابلة للقراءة.');let shared=[];if(zip.file('xl/sharedStrings.xml'))shared=elements(await xmlPart(zip,'xl/sharedStrings.xml'),'si').map(n=>elements(n,'t').map(t=>t.textContent).join(''));return {zip,sheets,shared,name:file.name};
}
async function readSheet(book,index){
 const sheet=book.sheets[index];if(!sheet)throw Error('اختر ورقة عمل صحيحة.');const doc=await xmlPart(book.zip,sheet.path);const rows=elements(doc,'row');if(rows.length>10001)throw Error('الحد الأقصى ١٠٠٠٠ صف في ورقة الاستيراد.');return rows.map((row,i)=>{const values=[];for(const cell of elements(row,'c')){const address=cell.getAttribute('r')||'';let col=0;for(const ch of (address.match(/^[A-Z]+/)||['A'])[0])col=col*26+ch.charCodeAt(0)-64;if(col>100)continue;const type=cell.getAttribute('t'),v=elements(cell,'v')[0]?.textContent;let value=type==='s'?(book.shared[+v]??''):type==='inlineStr'?elements(cell,'t').map(t=>t.textContent).join(''):(v??'');if(elements(cell,'f').length&&!v)value='[صيغة بلا قيمة محفوظة]';if(type==='e')value='[خطأ Excel]';values[col-1]=value}return {row:Number(row.getAttribute('r'))||i+1,values}}).filter(r=>r.values.some(v=>norm(v)));
}
function headerMap(values){const map={};for(const [key,aliases] of Object.entries(fieldNames)){const index=values.findIndex(v=>aliases.some(a=>norm(a)===norm(v)));if(index!==-1)map[key]=index}return map}
function answerIndex(value){const key=norm(value).replace(/^الخيار\s*/, '');const map={'أ':0,'ا':0,'ب':1,'ج':2,'د':3,a:0,b:1,c:2,d:3,'1':0,'2':1,'3':2,'4':3,'١':0,'٢':1,'٣':2,'٤':3};return Object.hasOwn(map,key)?map[key]:-1}
function questionProblems(q){const errors=[];for(const key of ['id','section','category','difficulty','text','explanation'])if(typeof q[key]!=='string'||!q[key].trim())errors.push('حقل '+({id:'معرف السؤال',section:'القسم',category:'التصنيف',difficulty:'الصعوبة',text:'السؤال',explanation:'الشرح'}[key])+' مطلوب');if(!['لفظي','كمي'].includes(q.section))errors.push('القسم يجب أن يكون لفظي أو كمي');if(!['سهل','متوسط','صعب'].includes(q.difficulty))errors.push('الصعوبة: سهل أو متوسط أو صعب');if(!Array.isArray(q.options)||q.options.length!==4||q.options.some(o=>typeof o!=='string'||!o.trim()))errors.push('أربعة خيارات غير فارغة مطلوبة');else if(new Set(q.options.map(norm)).size!==4)errors.push('الخيارات مكررة');if(!answered(q.answer))errors.push('الإجابة الصحيحة يجب أن تكون أ، ب، ج، د أو 1–4');if(q.id?.length>100||q.text?.length>15000||q.explanation?.length>15000||q.options?.some(o=>o.length>4000))errors.push('أحد الحقول أطول من الحد المقبول');if(JSON.stringify(q).includes('[صيغة بلا قيمة محفوظة]')||JSON.stringify(q).includes('[خطأ Excel]'))errors.push('أصلح أخطاء الصيغ وأعد حفظ الملف في Excel');return errors}
function fingerprint(q){return JSON.stringify([norm(q.text),q.options.map(norm)])}
function equalQuestion(a,b){return ['section','category','skill','difficulty','text','explanation'].every(k=>norm(a[k])===norm(b[k]))&&a.answer===b.answer&&fingerprint(a)===fingerprint(b)}
function analyzeRows(rows,allowUpdates=false){
 const headerIndex=rows.findIndex(r=>{const h=headerMap(r.values);return h.id!==undefined&&h.text!==undefined&&h.answer!==undefined});if(headerIndex<0)throw Error('لم نجد عناوين الأعمدة. استخدم القالب أو ورقة بنك_الأسئلة_1000.');const map=headerMap(rows[headerIndex].values),missing=requiredFields.filter(k=>map[k]===undefined);if(missing.length)throw Error('أعمدة مفقودة: '+missing.map(k=>fieldNames[k][0]).join('، '));const ids=new Set(),seen=new Map(data.questions.map(q=>[q.id,q])),fingerprints=new Map(data.questions.map(q=>[fingerprint(q),q.id]));const result={items:[],errors:[],skipped:[],newCount:0,updateCount:0,total:rows.length-headerIndex-1};
 for(const row of rows.slice(headerIndex+1)){const get=k=>String(row.values[map[k]]??'').trim();const q={id:get('id'),section:get('section'),category:get('category'),skill:get('skill'),difficulty:get('difficulty'),text:get('text'),options:['a','b','c','d'].map(get),answer:answerIndex(get('answer')),explanation:get('explanation'),source:get('source')||'ملف Excel مستورد'};let errors=questionProblems(q);if(ids.has(q.id))errors.push('المعرف مكرر داخل الورقة');ids.add(q.id);if(errors.length){result.errors.push({row:row.row,id:q.id,message:errors.join('؛ ')});continue}const old=seen.get(q.id),fp=fingerprint(q),other=fingerprints.get(fp);if(old&&equalQuestion(old,q)){result.skipped.push({row:row.row,id:q.id,message:'السؤال موجود دون تغيير'});continue}if(other&&other!==q.id){result.skipped.push({row:row.row,id:q.id,message:'نص وخيارات مكررة مع '+other});continue}if(old&&!allowUpdates){result.skipped.push({row:row.row,id:q.id,message:'المعرف موجود؛ فعّل تحديث المعرفات إذا قصدت تعديله'});continue}result.items.push(q);if(old)result.updateCount++;else result.newCount++;seen.set(q.id,q);fingerprints.set(fp,q.id)}return result;
}
function manage(){
 $('#main').innerHTML=title('إدارة الأسئلة والبيانات','إضافاتك ونتائجك محلية لهذا المتصفح. استخدم النسخة الاحتياطية لنقلها إلى جهاز آخر.')+`<section class="card"><div class="topline"><div><h2>١. أضف أسئلة من Excel</h2><p class="muted">${num(customQuestions.length)} سؤالًا مضافًا أو معدّلًا · ${num(data.questions.length)} في البنك الحالي</p></div><a class="download-link" href="GAT_Import_Template.xlsx" download>تنزيل قالب Excel</a></div><ol class="steps"><li>أدخل سؤالًا في كل صف مع خياراته الأربعة والإجابة الصحيحة والشرح.</li><li>احفظ بصيغة <b>.xlsx</b>، ثم اختر الملف وورقة الأسئلة.</li><li>راجع التقرير أدناه ثم اضغط اعتماد. لا تتم إضافة شيء بمجرد اختيار الملف.</li></ol><label class="file-label">ملف الأسئلة (بحد أقصى ١٥ MB)<input id="excel-file" type="file" accept=".xlsx"></label><div id="import-controls"></div><div id="import-preview" role="status"></div></section><div class="grid spaced"><section class="card"><h2>٢. احتفظ ببياناتك</h2><p>النسخة الاحتياطية تشمل إضافات الأسئلة، المحاولات، النتائج المفصّلة، والاختبار الجاري.</p><button id="backup" class="primary">تنزيل نسخة احتياطية JSON</button><label class="file-label spaced">استعادة نسخة احتياطية<input id="restore" type="file" accept=".json"></label><p class="muted">الاستعادة تستبدل بيانات هذا المتصفح بعد تأكيدك. نقل ملفات الموقع وحده لا ينقل نتائجك.</p></section><section class="card"><h2>٣. شغّل الموقع عندك</h2><p>نزّل الحزمة، فكّ الضغط، ثم افتح <b dir="ltr">index.html</b>. تشمل الأسئلة والمراجع ودليل الاستخدام، وتعمل دون إنترنت.</p><button class="primary" id="download-site">تنزيل الموقع كاملًا ZIP</button><p id="download-status" class="muted" role="status"></p><p class="muted">استورد نسخة بياناتك الاحتياطية داخل النسخة المحلية إذا أردت نقل نتائجك وإضافاتك. التصفير متاح في النسختين.</p></section></div><section class="card spaced reset-card"><h2>٤. ابدأ من جديد</h2><p>اختر نطاق التصفير. لن يُحذف شيء قبل التأكيد.</p><div class="actions"><button id="reset-progress">تصفير النتائج فقط</button><button id="reset-all" class="danger">إعادة ضبط كاملة</button></div><p class="muted">النتائج فقط: حذف المحاولات والاختبار الجاري مع إبقاء الأسئلة المضافة. الضبط الكامل: حذف النتائج والإضافات والعودة إلى البنك الأصلي (١٠٠٠ سؤال).</p></section>`;
 $('#excel-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;workbook=null;pendingImport=null;$('#import-controls').innerHTML='';$('#import-preview').textContent='جارٍ قراءة الملف…';try{workbook=await openWorkbook(f);const recommended=Math.max(0,workbook.sheets.findIndex(s=>s.name==='بنك_الأسئلة_1000'));$('#import-controls').innerHTML=`<div class="filters spaced"><label>ورقة العمل<select id="import-sheet">${workbook.sheets.map((s,i)=>`<option value="${i}" ${i===recommended?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label class="inline-check"><input id="allow-updates" type="checkbox"> تحديث الأسئلة ذات المعرف الموجود</label><button id="analyze">فحص البيانات</button></div>`;$('#import-preview').textContent='اختر ورقة الأسئلة ثم اضغط فحص البيانات. يُنصح بورقة بنك_الأسئلة_1000 لملفاتك الحالية.';$('#analyze').onclick=analyzeImport;$('#import-sheet').onchange=$('#allow-updates').onchange=()=>{pendingImport=null;$('#import-preview').textContent='تغيّر الاختيار. اضغط فحص البيانات مجددًا.'}}catch(err){$('#import-preview').textContent='تعذّرت قراءة الملف: '+err.message}};
 $('#backup').onclick=()=>{touchExam();downloadBlob('GAT_Backup_'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify(snapshot(),null,2),'application/json')};$('#restore').onchange=restoreBackup;$('#download-site').onclick=downloadSite;$('#reset-progress').onclick=()=>resetWorkspace(false);$('#reset-all').onclick=()=>resetWorkspace(true);if(location.protocol==='file:'){$('#download-site').disabled=true;$('#download-status').textContent='أنت تستخدم النسخة المحلية بالفعل. انسخ مجلد الموقع لنقله، وصدّر بياناتك الاحتياطية من هذا القسم.'}
}
async function analyzeImport(){pendingImport=null;$('#import-preview').textContent='جارٍ فحص الصفوف…';$('#analyze').disabled=true;try{const rows=await readSheet(workbook,+$('#import-sheet').value);pendingImport=analyzeRows(rows,$('#allow-updates').checked);pendingImport.sheet=workbook.sheets[+$('#import-sheet').value].name;pendingImport.filename=workbook.name;renderImport()}catch(err){$('#import-preview').textContent=err.message}finally{$('#analyze').disabled=false}}
function renderImport(){const r=pendingImport;$('#import-preview').innerHTML=`<div class="feedback"><b>نتيجة الفحص: ${num(r.total)} صفًا</b><p>${num(r.newCount)} جديد · ${num(r.updateCount)} تحديث · ${num(r.skipped.length)} متجاوز · ${num(r.errors.length)} غير صالح</p><p>المعاينة تتحقق من الحقول والتكرارات، ولا تثبت صحة الحل رياضيًا أو لغويًا.</p></div>${r.items.length?`<h3>معاينة الأسئلة المقبولة</h3><div class="table-wrap"><table><thead><tr><th>المعرف</th><th>السؤال</th><th>الإجابة الصحيحة</th></tr></thead><tbody>${r.items.slice(0,5).map(q=>`<tr><td>${esc(q.id)}</td><td>${esc(q.text.slice(0,180))}</td><td>${'أبجد'[q.answer]} — ${esc(q.options[q.answer])}</td></tr>`).join('')}</tbody></table></div><p class="muted">تظهر أول خمسة أسئلة للمراجعة.</p>`:''}${r.errors.length||r.skipped.length?`<details open><summary>الأخطاء والصفوف المتجاوزة</summary><div class="table-wrap"><table><thead><tr><th>صف Excel</th><th>المعرف</th><th>الملاحظة</th></tr></thead><tbody>${[...r.errors,...r.skipped].slice(0,100).map(e=>`<tr><td>${num(e.row)}</td><td>${esc(e.id)}</td><td>${esc(e.message)}</td></tr>`).join('')}</tbody></table></div><p class="muted">يعرض أول ١٠٠ ملاحظة؛ التقرير القابل للتنزيل يشمل جميع الصفوف.</p></details><button id="import-report">تنزيل تقرير الفحص CSV</button>`:''}<div class="actions"><button id="apply-import" class="primary" ${r.items.length?'':'disabled'}>اعتماد ${num(r.items.length)} سؤالًا صالحًا${r.errors.length?' وتجاوز الصفوف غير الصالحة':''}</button></div>`;$('#apply-import').onclick=applyImport;$('#import-report')?.addEventListener('click',()=>downloadBlob('GAT_Import_Review.csv','\ufeff'+[['الورقة','صف Excel','المعرف','الحالة','الملاحظة'],...r.errors.map(e=>[r.sheet,e.row,e.id,'خطأ',e.message]),...r.skipped.map(e=>[r.sheet,e.row,e.id,'متجاوز',e.message])].map(row=>row.map(v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8'))}
function applyImport(){const r=pendingImport;if(!r||!r.items.length)return;if(r.updateCount&&!confirm(`سيتم تحديث ${r.updateCount} سؤالًا في البنك. تبقى تقارير المحاولات السابقة كما كانت. هل تريد الاعتماد؟`))return;const before=customQuestions;const map=new Map(customQuestions.map(q=>[q.id,q]));r.items.forEach(q=>map.set(q.id,q));customQuestions=[...map.values()];if(!save()){customQuestions=before;$('#import-preview').textContent='لم تُعتمد الأسئلة لأن مساحة الحفظ غير كافية. صدّر نسخة احتياطية ثم قلّل حجم الدفعة.';return}rebuild();pendingImport=null;$('#import-preview').innerHTML=`<div class="feedback"><b>تم اعتماد ${num(r.items.length)} سؤالًا.</b><p>البنك الآن ${num(data.questions.length)} سؤالًا. إضافاتك متاحة عند اختيار البنك الكامل من إعدادات الأسئلة؛ ولا تُعد مراجعة علميًا بمجرد استيرادها.</p></div>`}
function checkedQuestion(q){if(!q||typeof q!=='object'||questionProblems(q).length)throw Error('سؤال غير صالح في النسخة الاحتياطية.');return {id:q.id,section:q.section,category:q.category,skill:typeof q.skill==='string'?q.skill:'',difficulty:q.difficulty,text:q.text,options:[...q.options],answer:q.answer,explanation:q.explanation,source:typeof q.source==='string'?q.source:''}}
function checkedExam(e,active=false){if(!e||typeof e.id!=='string'||typeof e.name!=='string'||!['random','fixed'].includes(e.mode)||!Array.isArray(e.qs)||e.qs.length<1||e.qs.length>1000)throw Error('سجل امتحان غير صالح.');const qs=e.qs.map(checkedQuestion);if(new Set(qs.map(q=>q.id)).size!==qs.length)throw Error('سجل امتحان فيه معرفات مكررة.');const n=qs.length;if(!Array.isArray(e.answers)||e.answers.length!==n||e.answers.some(a=>a!==null&&!answered(a))||!Array.isArray(e.times)||e.times.length!==n||e.times.some(t=>!Number.isFinite(t)||t<0)||!Array.isArray(e.flags)||e.flags.length!==n||e.flags.some(f=>typeof f!=='boolean'))throw Error('إجابات أو أوقات غير صالحة.');if(!Number.isFinite(e.startedAt)||!Number.isFinite(e.deadline)||e.deadline<e.startedAt||!Number.isInteger(e.index)||e.index<0||e.index>=n)throw Error('توقيت امتحان غير صالح.');if(!active&&(!Number.isFinite(e.finishedAt)||e.finishedAt<e.startedAt||e.finishedAt>e.deadline||!['submitted','timeout'].includes(e.reason)))throw Error('نتيجة غير صالحة.');return {id:e.id,name:e.name,mode:e.mode,qs,answers:[...e.answers],times:[...e.times],flags:[...e.flags],index:e.index,startedAt:e.startedAt,deadline:e.deadline,...(e.profile==='sectioned'?{profile:'sectioned',block:Math.max(0,Math.min(5,Number.isInteger(e.block)?e.block:0)),blockDeadline:Math.min(e.deadline,Number.isFinite(e.blockDeadline)?e.blockDeadline:e.deadline)}:{}),...(active?{lastTouch:Math.min(Date.now(),e.deadline)}:{finishedAt:e.finishedAt,reason:e.reason})}}
function validateBackup(s){if(!s||s.format!=='gat-workspace'||s.version!==2||!Array.isArray(s.customQuestions)||!Array.isArray(s.history)||!Array.isArray(s.attempts))throw Error('هذه ليست نسخة احتياطية متوافقة مع الموقع.');if(s.customQuestions.length>10000||s.history.length>100000||s.attempts.length>2000)throw Error('حجم بيانات النسخة أكبر من المسموح.');const custom=s.customQuestions.map(checkedQuestion);if(new Set(custom.map(q=>q.id)).size!==custom.length)throw Error('معرفات أسئلة مكررة.');const h=s.history.map(h=>{if(!h||typeof h.id!=='string'||typeof h.category!=='string'||typeof h.section!=='string'||typeof h.correct!=='boolean'||typeof h.at!=='string')throw Error('سجل محاولات غير صالح.');return {id:h.id,category:h.category,section:h.section,correct:h.correct,at:h.at,...(typeof h.examId==='string'?{examId:h.examId}:{})}});const a=s.attempts.map(e=>checkedExam(e));if(new Set(a.map(e=>e.id)).size!==a.length)throw Error('معرفات امتحانات مكررة.');const active=s.activeExam?checkedExam(s.activeExam,true):null;if(active&&a.some(e=>e.id===active.id))throw Error('المحاولة الجارية مكتملة بالفعل.');return {customQuestions:custom,history:h,attempts:a,settings:{mode:s.settings?.mode==='fixed'?'fixed':'random',large:!!s.settings?.large,goal:[10,20,30].includes(s.settings?.goal)?s.settings.goal:10,profile:['diagnostic','standard','sectioned'].includes(s.settings?.profile)?s.settings.profile:'standard'},activeExam:active}}
function applyState(s){customQuestions=s.customQuestions;history=s.history;attempts=s.attempts;settings=s.settings;exam=s.activeExam;large=!!settings.large;document.body.classList.toggle('large-text',large);$('#font').textContent=large?'ع −':'ع +';rebuild()}
async function restoreBackup(event){const f=event.target.files[0];if(!f)return;try{if(f.size>20*1024*1024)throw Error('حجم النسخة أكبر من ٢٠ ميجابايت.');const s=validateBackup(JSON.parse(await f.text()));if(!confirm(`ستستبدل بيانات هذا المتصفح بـ ${s.attempts.length} نتيجة امتحان و${s.customQuestions.length} سؤال مضاف/معدّل و${s.history.length} محاولة. نزّل نسخة من بياناتك الحالية أولًا عند الحاجة. هل تريد الاستعادة؟`))return;touchExam();const before=clone(snapshot());clearInterval(timer);applyState(s);if(!save()){applyState(validateBackup(before));if(exam)runTimer();throw Error('مساحة الحفظ غير كافية؛ بقيت بياناتك السابقة كما كانت.')}session=0;pendingImport=null;workbook=null;if(!exam)manage();if(exam){if(Date.now()>=exam.deadline)finishExam('timeout');else{activate('exams');renderExam();runTimer()}}alert('تمت استعادة البيانات بنجاح.')}catch(err){alert('لم تتم الاستعادة: '+err.message)}finally{event.target.value=''}}
function resetWorkspace(all){const message=all?'سيُحذف كل تقدمك ونتائج امتحاناتك وأسئلتك المستوردة ويُستعاد البنك الأصلي. لا يمكن التراجع دون نسخة احتياطية. هل تريد إعادة الضبط الكاملة؟':'ستُحذف نتائج الامتحانات ومحاولات التدريب والاختبار الجاري، مع الاحتفاظ بأسئلتك المستوردة. هل تريد تصفير النتائج؟';if(!confirm(message))return;const before=clone(snapshot());history=[];attempts=[];exam=null;if(all){customQuestions=[];settings={mode:'random',large:false}}if(!save()){applyState(validateBackup(before));alert('تعذّر حفظ التصفير، ولم تُحذف بياناتك.');return}clearInterval(timer);session=0;selected=null;checked=false;pendingImport=null;workbook=null;currentReport=null;large=!!settings.large;document.body.classList.toggle('large-text',large);$('#font').textContent=large?'ع −':'ع +';rebuild();manage();alert(all?'تمت إعادة الضبط إلى البنك الأصلي.':'تم تصفير النتائج مع الاحتفاظ بالأسئلة.')}
async function downloadSite(){const b=$('#download-site'),status=$('#download-status');b.disabled=true;status.textContent='جارٍ تجهيز الملفات والمراجع. قد يستغرق التنزيل قليلًا…';try{const paths=['index.html','style.css','account.js','data.js','core.js','app.js','learn.js','engine.js','qiyas.js','PROJECT_GUIDE.html','data.json','audit-batch-01.html','audit-batch-02.html','audit-batch-03.html','audit-batch-04.html','audit-batch-05.html','audit-batch-06.html','audit-batch-07.html','audit-batch-08.html','vendor/jszip.min.js','vendor/JSZip-LICENSE.md','GAT_Import_Template.xlsx','READ_ME.html','START_WINDOWS.bat','serve.py',...window.GAT_BASE.references.map(r=>r.url)];const zip=new JSZip();let count=0;for(const path of paths){const res=await fetch(path);if(!res.ok)throw Error('تعذّر تحميل '+path);zip.file('Qudrat_Offline/'+path,await res.arrayBuffer());count++;status.textContent=`تجهيز ${num(count)} من ${num(paths.length)} ملفًا…`}const blob=await zip.generateAsync({type:'blob',compression:'DEFLATE',compressionOptions:{level:3}});downloadBlob('Qudrat_Offline.zip',blob,'application/zip');status.textContent='بدأ تنزيل الحزمة الكاملة. فكّ الضغط ثم افتح index.html. صدّر نسخة بياناتك الاحتياطية لنقل النتائج.'}catch(err){status.textContent='لم يكتمل التنزيل: '+err.message+'؛ أعد المحاولة.'}finally{b.disabled=false}}
function registerTools(){if(!document.modelContext?.registerTool)return;const ac=new AbortController();addEventListener('pagehide',()=>ac.abort(),{once:true});for(const tool of [{name:'get_training_progress',description:'Read device-local practice totals and saved exam results.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({attempts:history.length,correct:history.filter(h=>h.correct).length,exams:attempts.map(e=>({id:e.id,name:e.name,...counts(e)}))})},{name:'start_training_exam',description:'Start a timed exam, persist it on this device, and show its first question.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['random','fixed']},name:{type:'string',enum:Object.keys(data.tests)}},required:['mode'],additionalProperties:false},execute:input=>{if(!input||!['random','fixed'].includes(input.mode)||exam||(input.mode==='fixed'&&!Object.hasOwn(data.tests,input.name)))throw Error('Invalid exam or another exam is running');startExam(input.mode==='random'?'اختبار متجدد':input.name,input.mode);return {started:true,id:exam.id,questions:exam.qs.length}}}])try{Promise.resolve(document.modelContext.registerTool(tool,{signal:ac.signal})).catch(()=>{})}catch{}}
function init(){
 if(!window.GAT_BASE?.questions?.length){$('#main').innerHTML='<section class="card"><h1>تعذّر تحميل الأسئلة</h1><p>تأكد من وجود data.js بجانب index.html، أو أعد تنزيل الحزمة.</p></section>';return}rebuild();
 try{const raw=localStorage.getItem(STORE);if(raw)applyState(validateBackup(JSON.parse(raw)));else{const old=JSON.parse(localStorage.getItem('gat-progress-v1')||'[]');if(Array.isArray(old))history=old.filter(h=>h&&typeof h.id==='string'&&typeof h.category==='string'&&typeof h.section==='string'&&typeof h.at==='string'&&typeof h.correct==='boolean')}}catch{warning('تعذّرت قراءة البيانات المحفوظة. يمكنك استعادة نسخة احتياطية من إدارة البيانات.');}
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>go(b.dataset.view));$('#font').onclick=()=>{large=!large;settings.large=large;document.body.classList.toggle('large-text',large);$('#font').textContent=large?'ع −':'ع +';save()};if(exam){if(Date.now()>=exam.deadline)finishExam('timeout');else{activate('exams');renderExam();runTimer()}}else render();registerTools();
}
addEventListener('beforeunload',()=>{if(exam){touchExam();save()}});
